import sys
from collections import defaultdict

def solve():
    n, m = map(int, input().split())
    graph = defaultdict(list)
    edges = []

    for _ in range(m):
        u, v = map(int, input().split())
        graph[u].append(v)
        graph[v].append(u)
        edges.append((u, v))

    colors = [-1] * (n + 1)

    def dfs(v, color):
        colors[v] = color
        for u in graph[v]:
            if colors[u] == -1:
                if not dfs(u, 1 - color):
                    return False
            elif colors[u] == color:
                return False
        return True

    if not dfs(1, 0):
        print("NO")
        return

    result = []
    for u, v in edges:
        result.append('0' if colors[u] == 0 else '1')

    print("YES")
    print(''.join(result))

if __name__ == "__main__":
    solve()
